def gen(draw):
    n = draw(st.integers(1, 8))
    vals = draw(st.sampled_from([(1, 2), (1, 3), (1, 5), (1, 10**9)]))
    cards = [
        (draw(st.integers(vals[0], vals[1])), draw(st.integers(vals[0], vals[1])))
        for _ in range(n)
    ]
    lines = [str(n)] + [f"{a} {b}" for a, b in cards]
    return "\n".join(lines) + "\n"

