    if len(t) < 1:
        return False
    try:
        n = int(t[0])
    except ValueError:
        return False
    if not (1 <= n <= 18):
        return False
    if len(t) != 1 + 2 * n:
        return False
    try:
        vals = [int(x) for x in t[1:]]
    except ValueError:
        return False
    return all(1 <= v <= 10**9 for v in vals)

